         CREATE TEMP TABLE x_keys(__path TEXT NOT NULL,key,compact INTEGER NOT NULL);
         INSERT INTO x_keys SELECT __path,key,row_number() OVER(ORDER BY __path,key) FROM (
           SELECT __path,id AS key FROM x_roots UNION SELECT __path,src FROM x_edges UNION SELECT __path,dst FROM x_edges);
         CREATE UNIQUE INDEX x_key_text ON x_keys(__path,key);
         CREATE UNIQUE INDEX x_key_int ON x_keys(compact);
         CREATE TEMP TABLE x_compact AS SELECT a.compact AS src,b.compact AS dst FROM x_edges e
           JOIN x_keys a ON a.__path=e.__path AND a.key=e.src JOIN x_keys b ON b.__path=e.__path AND b.key=e.dst;
         CREATE INDEX x_forward ON x_compact(src,dst);
         CREATE TEMP TABLE x_requests(root INTEGER PRIMARY KEY);
         INSERT INTO x_requests SELECT k.compact FROM x_roots r JOIN x_keys k ON k.__path=r.__path AND k.key=r.id;
